if (!(Test-Path $reference)) {
  Invoke-WebRequest -UseBasicParsing -Uri $uri -OutFile $reference
}
if ((Get-FileHash $reference -Algorithm SHA256).Hash.ToLower() -ne '03964dedcf8b7f4ebde24cd3d0738873d37c075a7a9b313dad001bb937f9d1b6') {
  throw 'StudioRender reference differs from the actual audited user sample'
}
python -m pip install pefile==2024.8.26 capstone==5.0.6
if ($LASTEXITCODE -ne 0) { throw 'Read-only inspector dependencies failed' }
python "$PSScriptRoot/inspect_studiorender.py" $reference --require-known --output "$out/disassembly.json"
