try {
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX /DNOMINMAX /DREMIX_BRIDGE_CLIENT /DL4D2_STUDIO_TEST "/I$source/bridge/src/client" "/I$source/bridge/src/util" "$root/tests/studio_model_native.cpp" "$source/bridge/src/client/studio_model_diagnostics.cpp" "$source/bridge/src/util/studio_model_context.cpp" "$source/bridge/src/util/exception_diagnostics.cpp" /Fe:studio-test.exe /link psapi.lib bcrypt.lib
  if ($LASTEXITCODE -ne 0) { throw 'Studio diagnostic x86 native compilation failed' }
  Assert-NativeArchitecture -Path "$out/studio-test.exe" -Architecture x86
